let fila = [];
try {
  fila = $('Code - Montar Fila de Envios').all().map(i => i.json);
} catch (e) {
  fila = [];
}

const desculpas = fila.filter(f => f.TIPO_ENVIO === 'DESCULPAS').length;
const dados = fila.filter(f => f.TIPO_ENVIO === 'DADOS').length;

return [{
  json: {
    status: (desculpas + dados) ? 'CONCLUIDO' : 'SEM_ENVIOS',
    emails_desculpas: desculpas,
    emails_dados_corretos: dados,
    mensagem: (desculpas + dados)
      ? 'Correção enviada: primeiro as erratas, depois os avisos com os dados corretos.'
      : 'Nenhum aluno com e-mail válido encontrado.'
  }
}];
